תקשיב תבדוק את הקוד ותגיד עם הוא בטוח ?<div id="app"><div id="chat"></div>
<input id="q" placeholder="שאל את BIRGSOL...">
<button onclick="send()">שלח</button></div>
<script>
async function send(){
let v=q.value; chat.innerHTML+=`<p><b>אתה:</b> ${v}</p>`;
let r=await fetch("/api/chat",{method:"POST",body:JSON.stringify({q:v})});
let d=await r.json(); chat.innerHTML+=`<p><b>AI:</b> ${d.a}</p>`; q.value=""
}
</script>
